function selectClip(id,scroll=false){if(state.busy==='previewing'){toast('Espera a que termine la operación actual.');return;}if(timelineEditor.drag)timelineEditor.pointerEnd({pointerId:timelineEditor.drag.pointerId},true);video.pause();state.selected=id;const clip=selected();if(!clip)return;state.view='edited';$('editedView').classList.add('active');$('originalView').classList.remove('active');$('editedView').setAttribute('aria-pressed','true');$('originalView').setAttribute('aria-pressed','false');video.currentTime=clip.start;renderClips();syncEditor();setTool('edit');timelineEditor.ensureVisible();if(scroll){$('previewSection').scrollIntoView({behavior:'smooth',block:'start'});$('previewSection').focus({preventScroll:true});}}
