async function playPause(){if(!state.meta)return;if(video.paused){const c=selected();if(c&&state.view==='edited'&&(video.currentTime<c.start||video.currentTime>=c.end-.04))video.currentTime=c.start;try{await video.play();}catch{toast('No se pudo reproducir la vista previa. Comprueba el formato del video.');}}else video.pause();}
