function updateTimelineSelection(){timelineEditor?.sync();}
function projectData(){return {application:'ClipForge',version:1,source:{name:state.file.name,size:state.file.size,lastModified:state.file.lastModified},game:state.game,fortnite:getDetectorControls(),events:state.events,video:state.fullVideo?{title:state.fullVideo.title,settings:state.fullVideo.settings}:null,editingFullVideo:isFullVideo(),clips:state.clips.map(({thumb,...c})=>c)};}
