function applyProject(project){if(project.application!=='ClipForge'||project.version!==1||!Array.isArray(project.clips))throw new Error('Ese archivo no es un proyecto de ClipForge compatible.');if(!state.file||!state.meta)throw new Error('Carga primero el video original de este proyecto.');if(project.source?.name!==state.file.name||project.source?.size!==state.file.size)throw new Error(`Este proyecto corresponde a «${project.source?.name||'otro archivo'}». Carga ese video antes de abrirlo.`);const clips=restoreClips(project.clips,state.meta.duration);discardThumbs();state.histories.clear();state.clips=clips;state.events=restoreKillEvents(project.events||clips.flatMap(c=>c.killEvents||[]),state.meta.duration);if(project.fortnite)setDetectorControls(project.fortnite);restoreVideoEdits(project);if(['fortnite','minecraft'].includes(project.game))setGame(project.game);renderClips();syncEditor();persist();$('analysisSummary').textContent='Proyecto restaurado. Se conservan los tiempos de recorte y todos sus ajustes.';toast('Proyecto abierto.');}
function setGame(game){state.game=game;$$('[data-game]').forEach(b=>{b.classList.toggle('active',b.dataset.game===game);b.setAttribute('aria-pressed',String(b.dataset.game===game));});syncDetectorControls();}
