$('clipTitle').addEventListener('input',e=>{const c=selected();if(!c)return;const before=snapshot(c);c.title=e.target.value.slice(0,70);commitHistory(before,'title');$('selectedName').textContent=c.title;$('monitorClipName').textContent=c.title;renderClips();persist();});for(const id of ['trimStart','startRange'])$(id).addEventListener(id==='trimStart'?'change':'input',e=>{const c=selected();if(c)setTrim(Math.min(Number(e.target.value),c.end-.1),c.end,true);});for(const id of ['trimEnd','endRange'])$(id).addEventListener(id==='trimEnd'?'change':'input',e=>{const c=selected();if(c)setTrim(c.start,Number(e.target.value));});$('markStart').addEventListener('click',()=>{const c=selected();if(c)setTrim(Math.min(video.currentTime,c.end-.1),c.end);});$('markEnd').addEventListener('click',()=>{const c=selected();if(c)setTrim(c.start,Math.max(video.currentTime,c.start+.1));});
$$('[data-tab]').forEach(b=>b.addEventListener('click',()=>{$$('[data-tab]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-selected',String(x===b));});$$('.settings-tab').forEach(x=>x.hidden=x.id!=='tab-'+b.dataset.tab);}));$$('[data-ratio]').forEach(b=>b.addEventListener('click',()=>{updateSettings({ratio:b.dataset.ratio});syncEditor();renderClips();}));$('fitMode').addEventListener('change',e=>{updateSettings({fit:e.target.value});syncEditor();});for(const id of ['brightness','contrast','saturation','cropX','cropY','volume'])$(id).addEventListener('input',e=>{$(id+'Out').textContent=e.target.value+'%';updateSettings({[id]:Number(e.target.value)});if(['brightness','contrast','saturation'].includes(id))$$('[data-look]').forEach(x=>x.classList.remove('active'));});
function setLook(name){const look={natural:[100,100,100],vivid:[103,111,125],night:[124,97,106],cinema:[97,113,85]}[name];updateSettings({brightness:look[0],contrast:look[1],saturation:look[2],...(name==='natural'?{sharpness:0}:{})});syncEditor();$$('[data-look]').forEach(b=>b.classList.toggle('active',b.dataset.look===name));}$$('[data-look]').forEach(b=>b.addEventListener('click',()=>setLook(b.dataset.look)));$('resetImage').addEventListener('click',()=>setLook('natural'));$('overlayText').addEventListener('input',e=>updateSettings({text:e.target.value}));$('textPosition').addEventListener('change',e=>updateSettings({textPosition:e.target.value}));$('textStyle').addEventListener('change',e=>updateSettings({textStyle:e.target.value}));$('clipWatermark').addEventListener('change',e=>updateSettings({watermark:e.target.checked}));
$('editFullVideoBtn').addEventListener('click',()=>{if(!state.meta||state.busy)return;selectClip(FULL_VIDEO_ID);setTool('quality');timelineEditor.setRange(0,state.meta.duration);persist();});
$('exportFullVideoBtn').addEventListener('click',()=>openExport('full'));$('exportScope').addEventListener('change',updateExportSpec);
$('exportBtn').addEventListener('click',()=>openExport());$('exportForm').addEventListener('submit',startExport);for(const [id,key] of [['exportResolution','exportResolution'],['exportFps','exportFps'],['exportQuality','exportQuality']])$(id).addEventListener('change',()=>{if(id==='exportFps')changeFps($(id).value);else{updateSettings({[key]:id==='exportResolution'?Number($(id).value):$(id).value});updateExportSpec();}});$('exportFormat').addEventListener('change',updateExportSpec);$('exportDirect').addEventListener('change',syncExportDestination);
$$('[data-close]').forEach(b=>b.addEventListener('click',()=>{if((b.dataset.close==='sampleDialog'&&state.busy==='previewing')){toast('Cancela la prueba o espera a que termine.');return;}if(b.dataset.close==='sampleDialog')pauseSamples();$(b.dataset.close).close();}));$('helpBtn').addEventListener('click',()=>$('helpDialog').showModal());$('projectMenuBtn').addEventListener('click',()=>$('projectDialog').showModal());$('navExports').addEventListener('click',()=>exportPanel.open());$('navStudio').addEventListener('click',()=>window.scrollTo({top:0,behavior:'smooth'}));$('navClips').addEventListener('click',()=>$('clipsSection').scrollIntoView({behavior:'smooth'}));
$('saveProjectBtn').addEventListener('click',()=>{if(!state.file||!state.meta)return;downloadBlob(new Blob([JSON.stringify(projectData(),null,2)],{type:'application/json'}),safeName(state.file.name.replace(/\.[^.]+$/,''))+'.clipforge.json');toast('Proyecto descargado. Conserva también tu video original.');});$('openProjectBtn').addEventListener('click',()=>{if(!state.meta){toast('Carga primero el video original de tu proyecto.');return;}$('projectInput').click();});$('projectInput').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>2*1024*1024)throw new Error('El archivo de proyecto es demasiado grande.');applyProject(JSON.parse(await file.text()));$('projectDialog').close();await refreshThumbnails();}catch(error){toast(error.message,10000);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('exportsPanel').hidden&&!document.querySelector('dialog[open]')){exportPanel.close();return;}if(e.target.closest?.('#exportsPanel,#exportQueueToggle'))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'&&!['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();changeHistory(e.shiftKey?'redo':'undo');return;}if(document.querySelector('dialog[open]')||['INPUT','TEXTAREA','SELECT','BUTTON'].includes(e.target.tagName)||e.ctrlKey||e.metaKey||e.altKey)return;if(e.code==='Space'){e.preventDefault();playPause();}else if(e.key.toLowerCase()==='i')$('markStart').click();else if(e.key.toLowerCase()==='o')$('markEnd').click();});window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(drawTimeline,120);});window.addEventListener('beforeunload',e=>{if(exportQueue.hasPending||state.busy==='analyzing'||state.busy==='previewing'){e.preventDefault();e.returnValue='';}if(state.file&&state.meta)try{localStorage.setItem(fileKey(),JSON.stringify(projectData()));}catch{}});
if(!supportsMedia){$('compatibility').hidden=false;$('compatibility').textContent='Para analizar y exportar videos, abre ClipForge en Chrome o Edge actualizado en computadora. Este navegador no ofrece todas las funciones de video necesarias.';}syncDetectorControls();setBusy(null);drawTimeline();
